// Traduit les constats de la route en une alerte lisible d'un coup d'oeil.
//
// PAS DE MARKDOWN. Un texte Telegram en Markdown contenant _ ou * fait echouer
// l'envoi et rend la panne silencieuse — c'est deja arrive. Texte brut.
const r = $input.first().json;

// Une reponse qui n'est pas `ok` n'est pas « zero silence » : c'est une
// anomalie. La taire ferait passer une sonde cassee pour une chaine saine.
if (!r || r.ok !== true) {
  return [{ json: { message:
    'SONDE SANTE - reponse inattendue\n' +
    'La route a repondu sans ok:true. Rien ne surveille la chaine tant que ceci dure.\n\n' +
    JSON.stringify(r).slice(0, 300) } }];
}

// Rien a signaler : on n'envoie rien. Un moniteur qui parle tous les quarts
// d'heure pour dire « tout va bien » cesse d'etre lu.
if (!r.total) return [];

const lisible = (min) => {
  const h = Math.floor(min / 60), m = min % 60;
  return h ? h + ' h ' + String(m).padStart(2, '0') : m + ' min';
};

const titres = {
  sans_livreur: 'sans livreur',
  stock_non_decompte: 'stock non decompte',
  abandons_en_retard: 'abandons en retard',
};

const resume = Object.entries(r.par_type)
  .filter(([, n]) => n > 0)
  .map(([k, n]) => n + ' ' + (titres[k] || k))
  .join(', ');

const lignes = r.constats.map((c) =>
  '- ' + c.boutique + ' / ' + c.reference + '\n  ' + c.detail + ' (depuis ' + lisible(c.age_minutes) + ')');

return [{ json: { message:
  'SANTE DE LA CHAINE - ' + r.total + ' silence(s)\n' +
  resume + '\n' +
  'Boutiques : ' + r.boutiques.join(', ') + '\n\n' +
  lignes.join('\n') } }];

// LA SONDE ELLE-MEME EST TOMBEE.
//
// C'est le cas qu'un moniteur oublie le plus souvent : il se tait quand il est
// casse, et son silence se lit comme « tout va bien ». Le noeud HTTP reessaie
// trois fois avant d'arriver ici, pour qu'un seul fetch rate ne crie pas au
// loup — une sonde qui a deja annonce une panne inexistante n'est plus crue.
const e = $input.first().json;
const detail = String(e?.error?.message ?? e?.message ?? JSON.stringify(e)).slice(0, 300);

return [{ json: { message:
  'SONDE SANTE INJOIGNABLE\n' +
  'La route /api/internal/sante n a pas repondu apres trois essais.\n' +
  'Tant que ce message revient, plus rien ne surveille la chaine.\n\n' +
  detail } }];
